INSERT INTO products (id, category_id, name, image_url, original_price, price, delivery_badge, delivery_text, rating, review_count, reward_amount, detail_description) VALUES
(1, (SELECT id FROM categories WHERE name = '스킨케어'), '수분 진정 크림 100ml, 1개', 'https://picsum.photos/seed/cream1/400/400', 19000, 15200, '빠른배송', '내일 도착', 4.6, 3201, 300, '건조하고 예민한 피부에 수분과 진정 케어를 동시에 더해주는 크림입니다. 산뜻한 제형으로 끈적임 없이 흡수되며, 아침·저녁 데일리 케어로 사용하기 좋습니다.'),
(2, (SELECT id FROM categories WHERE name = '스킨케어'), '순면 화장솜, 300매, 1개', 'https://picsum.photos/seed/cotton2/400/400', 5000, 4250, '빠른배송', '내일 도착', 4.8, 15234, 80, '100% 순면 소재로 자극이 적고 보풀이 적게 발생하는 화장솜입니다. 토너 정리, 포인트 메이크업 제거 등 다양한 용도로 활용할 수 있습니다.'),
(3, (SELECT id FROM categories WHERE name = '스킨케어'), '저자극 진정 토너 200ml', 'https://picsum.photos/seed/toner3/400/400', NULL, 12900, '빠른배송', '모레 도착', 4.4, 982, 200, '약산성 포뮬러로 피부 자극을 최소화한 진정 토너입니다. 세안 후 결을 정돈하고 다음 단계 흡수를 도와줍니다.'),
(4, (SELECT id FROM categories WHERE name = '메이크업'), '벨벳 립 틴트, 오렌지, 1개', 'https://picsum.photos/seed/tint4/400/400', 12000, 8400, '빠른배송', '내일 도착', 4.7, 5643, 150, '매트한 벨벳 텍스처로 밀착력이 뛰어난 립 틴트입니다. 얇게 발라도 선명한 발색을 오래 유지합니다.'),
(5, (SELECT id FROM categories WHERE name = '선케어'), '수딩 선크림 SPF50+ 50ml', 'https://picsum.photos/seed/sun5/400/400', 19000, 17100, '빠른배송', '내일 도착', 4.5, 2210, 340, 'SPF50+/PA++++ 자외선 차단 지수로 강한 자외선을 효과적으로 막아주면서도 백탁 없이 산뜻하게 마무리됩니다.'),
(6, (SELECT id FROM categories WHERE name = '클렌징'), '약산성 클렌징 폼 150g', 'https://picsum.photos/seed/cleanse6/400/400', NULL, 9900, '판매자배송', '3일 내 도착', 4.3, 764, 0, '풍성한 거품이 모공 속 노폐물과 메이크업 잔여물을 부드럽게 씻어내면서도 피부 당김 없이 촉촉함을 유지시켜 줍니다.'),
(7, (SELECT id FROM categories WHERE name = '원두/음료'), '유기농 원두커피 원두 1kg', 'https://picsum.photos/seed/coffee7/400/400', 24000, 18000, '빠른배송', '내일 도착', 4.9, 8821, 360, '유기농 인증 원두를 은은한 산미와 고소한 풍미로 로스팅했습니다. 핸드드립, 에스프레소 모두 잘 어울립니다.'),
(8, (SELECT id FROM categories WHERE name = '신선식품'), '무항생제 신선 계란 30구', 'https://picsum.photos/seed/egg8/400/400', NULL, 7980, '빠른배송', '내일 도착', 4.6, 4102, 160, '무항생제 인증 농장에서 매일 수거한 신선한 계란입니다. 산란일자를 표기하여 신선도를 확인할 수 있습니다.'),
(9, (SELECT id FROM categories WHERE name = '간식/과자'), '견과류 선물세트, 1세트', 'https://picsum.photos/seed/nuts9/400/400', 30000, 26400, '판매자배송', '2일 내 도착', 4.4, 512, 500, '아몬드, 캐슈넛, 호두 등 인기 견과류를 소포장으로 담은 선물세트입니다. 명절 선물이나 답례품으로 좋습니다.'),
(10, (SELECT id FROM categories WHERE name = '침구'), '극세사 이불세트, 퀸, 1세트', 'https://picsum.photos/seed/bedding10/400/400', 59500, 35700, '빠른배송', '내일 도착', 4.5, 1893, 700, '부드러운 극세사 원단으로 사계절 사용하기 좋은 이불세트입니다. 이불커버, 베개커버가 함께 구성되어 있습니다.'),
(11, (SELECT id FROM categories WHERE name = '청소/세탁'), '무선 청소기 호환 필터, 2개', 'https://picsum.photos/seed/filter11/400/400', NULL, 14500, '판매자배송', '3일 내 도착', 4.2, 233, 0, '주요 무선 청소기 모델과 호환되는 교체용 필터 2개 구성입니다. 정기 교체로 흡입력을 유지할 수 있습니다.'),
(12, (SELECT id FROM categories WHERE name = '방향/탈취'), '섬유 방향제 리필 세트, 3개', 'https://picsum.photos/seed/scent12/400/400', 14000, 11480, '빠른배송', '모레 도착', 4.6, 3390, 220, '은은하게 오래 지속되는 섬유 방향제 리필 3개 구성입니다. 침구, 커튼, 옷장 등에 사용하기 좋습니다.'),
(13, (SELECT id FROM categories WHERE name = '소형가전'), '미니 가습기 3L, 1개', 'https://picsum.photos/seed/humid13/400/400', 29000, 22900, '빠른배송', '내일 도착', 4.5, 1200, 400, '3L 대용량 물통으로 최대 12시간 연속 가동이 가능한 미니 가습기입니다. 사무실, 침실 등 소형 공간에 적합합니다.'),
(14, (SELECT id FROM categories WHERE name = 'PC/주변기기'), '무소음 무선 마우스, 1개', 'https://picsum.photos/seed/mouse14/400/400', NULL, 15900, '빠른배송', '내일 도착', 4.6, 3400, 220, '클릭 소음을 줄인 무소음 스위치와 2.4GHz 무선 연결을 지원하는 마우스입니다. 사무실, 도서관 등에서 사용하기 좋습니다.'),
(15, (SELECT id FROM categories WHERE name = '운동복/신발'), '쿠셔닝 런닝화, 남성용, 1켤레', 'https://picsum.photos/seed/shoes15/400/400', 59000, 39900, '빠른배송', '내일 도착', 4.7, 2100, 600, '쿠셔닝 미드솔이 착지 충격을 흡수해 장거리 러닝에도 편안한 운동화입니다. 통기성 좋은 메쉬 소재를 사용했습니다.'),
(16, (SELECT id FROM categories WHERE name = '캠핑용품'), '원터치 텐트, 2~3인용, 1개', 'https://picsum.photos/seed/tent16/400/400', 89000, 68000, '판매자배송', '2일 내 도착', 4.4, 430, 900, '펼치기만 하면 바로 설치되는 원터치 방식의 2~3인용 텐트입니다. 초경량 설계로 휴대와 보관이 간편합니다.');
